#!/usr/bin/env node
// Story 18-1 — vendor React's Flight client into the gem.
//
// ruact decodes Flight with `react-server-dom-webpack/client.browser`, the
// client React publishes (docs/internal/decisions/flight-client-compatibility.md).
// The npm package declares `webpack` as a required peer, so the gem ships its
// own copy instead (packaging option C); an app that installs
// `react-server-dom-webpack` itself gets that one (see `flightClientSource` in
// ../index.js).
//
// The published files are CommonJS. The runtime is served from the gem's
// directory, which Vite does not pre-bundle, so this script wraps each one as
// an ES module:
//
//   - `require("react")` / `require("react-dom")` become imports of the app's
//     React (one React instance);
//   - `__webpack_require__` / `__webpack_chunk_load__` become module-local
//     functions over ruact's component registry (../runtime/flight-modules.js),
//     so nothing named after webpack lands on `globalThis`;
//   - `process.env.NODE_ENV` is fixed per variant.
//
// Usage: node scripts/vendor-flight-client.mjs   (writes runtime/vendor/…)
// Re-running with the same VERSION/INTEGRITY writes identical bytes.

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const PACKAGE = "react-server-dom-webpack";
export const VERSION = "19.3.0";
const INTEGRITY =
  "sha512-ymt9RkvWtW4OpIhWf1wj4u5CxnBaVbDCkz/bw3/QFmOE7+/wg8C30uiJ/QqkEdWn/UqT5c7/rOUW/eWYMwceCg==";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const OUT_DIR = path.join(HERE, "..", "runtime", "vendor", PACKAGE);

// What the client exports (both variants export the same names).
const EXPORTS = [
  "createFromFetch",
  "createFromReadableStream",
  "createServerReference",
  "createTemporaryReferenceSet",
  "encodeReply",
  "registerServerReference",
];

const VARIANTS = {
  production: "cjs/react-server-dom-webpack-client.browser.production.js",
  development: "cjs/react-server-dom-webpack-client.browser.development.js",
};

function fetchTarball(workDir) {
  const out = execFileSync("npm", ["pack", `${PACKAGE}@${VERSION}`, "--silent", "--pack-destination", workDir], {
    encoding: "utf8",
  });
  const file = path.join(workDir, out.trim().split("\n").pop());
  const digest = `sha512-${createHash("sha512").update(fs.readFileSync(file)).digest("base64")}`;
  if (digest !== INTEGRITY) {
    throw new Error(`${PACKAGE}@${VERSION}: integrity mismatch\n  expected ${INTEGRITY}\n  got      ${digest}`);
  }
  execFileSync("tar", ["-xzf", file, "-C", workDir]);
  return path.join(workDir, "package");
}

export function wrap(cjsSource, mode) {
  const usesReact = cjsSource.includes('require("react")');
  const header = [
    `// GENERATED by scripts/vendor-flight-client.mjs from ${PACKAGE}@${VERSION}`,
    `// (${VARIANTS[mode]}, MIT — see LICENSE). Do not edit; re-run the script.`,
    usesReact ? 'import React from "react";' : null,
    'import ReactDOM from "react-dom";',
    'import { requireModule, loadChunk } from "../../flight-modules.js";',
    "",
    "const module = { exports: {} };",
    "const exports = module.exports;",
    `const process = { env: { NODE_ENV: ${JSON.stringify(mode)} } };`,
    "function require(id) {",
    usesReact ? '  if (id === "react") return React;' : null,
    '  if (id === "react-dom") return ReactDOM;',
    '  throw new Error("[ruact] vendored Flight client required an unexpected module: " + id);',
    "}",
    "// What webpack's runtime would provide, over ruact's component registry.",
    "function __webpack_require__(id) { return requireModule(id); }",
    "function __webpack_chunk_load__(chunkId) { return loadChunk(chunkId); }",
    "function __webpack_get_script_filename__(chunkId) { return chunkId; }",
    "",
    "(function () {",
  ].filter((line) => line !== null);
  const footer = [
    "})();",
    "",
    ...EXPORTS.map((name) => `export const ${name} = module.exports.${name};`),
    "",
  ];
  return `${header.join("\n")}\n${cjsSource.trimEnd()}\n${footer.join("\n")}`;
}

function main() {
  const workDir = fs.mkdtempSync(path.join(os.tmpdir(), "ruact-vendor-"));
  try {
    const pkg = fetchTarball(workDir);
    fs.mkdirSync(OUT_DIR, { recursive: true });
    for (const [mode, rel] of Object.entries(VARIANTS)) {
      const source = fs.readFileSync(path.join(pkg, rel), "utf8");
      for (const name of EXPORTS) {
        if (!source.includes(`exports.${name} =`)) throw new Error(`${rel}: export ${name} not found`);
      }
      fs.writeFileSync(path.join(OUT_DIR, `client.browser.${mode}.js`), wrap(source, mode));
    }
    fs.copyFileSync(path.join(pkg, "LICENSE"), path.join(OUT_DIR, "LICENSE"));
    fs.writeFileSync(
      path.join(OUT_DIR, "VERSION.json"),
      `${JSON.stringify({ package: PACKAGE, version: VERSION, integrity: INTEGRITY }, null, 2)}\n`,
    );
    console.log(`vendored ${PACKAGE}@${VERSION} → ${path.relative(process.cwd(), OUT_DIR)}`);
  } finally {
    fs.rmSync(workDir, { recursive: true, force: true });
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
